import bcrypt from "bcryptjs";
import { SignJWT, jwtVerify } from "jose";
import { cookies } from "next/headers";
import { NextRequest } from "next/server";

const JWT_SECRET = process.env.JWT_SECRET || "umgn_production_jwt_super_secret_key_change_me_987654321_secure";
const key = new TextEncoder().encode(JWT_SECRET);

export interface TokenPayload {
  userId: string;
  username: string;
  email: string;
}

export const AUTH_COOKIE_NAME = "umgn_token";

export async function hashPassword(password: string): Promise<string> {
  const salt = await bcrypt.genSalt(12);
  return bcrypt.hash(password, salt);
}

export async function comparePassword(password: string, hash: string): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

export async function signToken(payload: TokenPayload): Promise<string> {
  return new SignJWT({ ...payload })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("7d")
    .sign(key);
}

export async function verifyToken(token: string): Promise<TokenPayload | null> {
  try {
    const { payload } = await jwtVerify(token, key);
    return {
      userId: payload.userId as string,
      username: payload.username as string,
      email: payload.email as string,
    };
  } catch {
    return null;
  }
}

export async function getSessionFromCookies(): Promise<TokenPayload | null> {
  try {
    const cookieStore = cookies();
    const token = cookieStore.get(AUTH_COOKIE_NAME)?.value;
    if (!token) return null;
    return verifyToken(token);
  } catch {
    return null;
  }
}

export async function getAuthUser(req: NextRequest | Request): Promise<TokenPayload | null> {
  let token: string | undefined;

  // 1. Check Authorization header
  const authHeader = req.headers.get("authorization");
  if (authHeader && authHeader.startsWith("Bearer ")) {
    token = authHeader.substring(7);
  }

  // 2. Check Cookie header if no Bearer token
  if (!token) {
    const cookieHeader = req.headers.get("cookie");
    if (cookieHeader) {
      const match = cookieHeader.match(new RegExp(`(^|;\\s*)${AUTH_COOKIE_NAME}=([^;]+)`));
      if (match) {
        token = match[2];
      }
    }
  }

  if (!token) return null;
  return verifyToken(token);
}

export const authCookieOptions = {
  name: AUTH_COOKIE_NAME,
  httpOnly: true,
  secure: process.env.NODE_ENV === "production",
  sameSite: "strict" as const,
  path: "/",
  maxAge: 7 * 24 * 60 * 60, // 7 days in seconds
};

interface RateLimitRecord {
  count: number;
  resetTime: number;
}

const tracker = new Map<string, RateLimitRecord>();

// Automatically clean up old rate limit entries every 5 minutes
if (typeof setInterval !== "undefined") {
  setInterval(() => {
    const now = Date.now();
    for (const [key, record] of tracker.entries()) {
      if (now > record.resetTime) {
        tracker.delete(key);
      }
    }
  }, 5 * 60 * 1000);
}

export interface RateLimitOptions {
  limit: number;
  windowMs: number;
}

export function rateLimit(
  identifier: string,
  options: RateLimitOptions = { limit: 60, windowMs: 60 * 1000 }
): { success: boolean; limit: number; remaining: number; resetTime: number } {
  const now = Date.now();
  const record = tracker.get(identifier);

  if (!record || now > record.resetTime) {
    tracker.set(identifier, {
      count: 1,
      resetTime: now + options.windowMs,
    });
    return {
      success: true,
      limit: options.limit,
      remaining: options.limit - 1,
      resetTime: now + options.windowMs,
    };
  }

  if (record.count < options.limit) {
    record.count += 1;
    return {
      success: true,
      limit: options.limit,
      remaining: options.limit - record.count,
      resetTime: record.resetTime,
    };
  }

  return {
    success: false,
    limit: options.limit,
    remaining: 0,
    resetTime: record.resetTime,
  };
}

export function validateEmail(email: string): boolean {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email) && email.length <= 120;
}

export function validateUsername(username: string): boolean {
  const usernameRegex = /^[a-zA-Z0-9_]{3,30}$/;
  return usernameRegex.test(username);
}

export function validatePassword(password: string): { valid: boolean; message?: string } {
  if (password.length < 8) {
    return { valid: false, message: "Password must be at least 8 characters long." };
  }
  if (password.length > 100) {
    return { valid: false, message: "Password must not exceed 100 characters." };
  }
  return { valid: true };
}

export function sanitizeText(input: string): string {
  if (typeof input !== "string") return "";
  // Strip control characters except newline and tab
  return input.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, "");
}

export interface ChatHistoryItem {
  role: "user" | "assistant" | "system";
  content: string;
}

export interface StreamLLMOptions {
  messages: ChatHistoryItem[];
  systemPrompt?: string;
  model?: string;
  temperature?: number;
  onChunk: (chunk: string) => void;
}

export async function streamLLMResponse(options: StreamLLMOptions): Promise<string> {
  const { messages, systemPrompt, model = "gemini-1.5-flash", temperature = 0.7, onChunk } = options;
  const geminiKey = process.env.GEMINI_API_KEY?.trim();
  const openaiKey = process.env.OPENAI_API_KEY?.trim();

  // 1. Check for Gemini API Key
  if (geminiKey) {
    try {
      const fullResponse = await callGeminiStreaming(geminiKey, model, systemPrompt, messages, temperature, onChunk);
      return fullResponse;
    } catch (err) {
      console.error("Gemini API stream error, falling back to local engine:", err);
    }
  }

  // 2. Check for OpenAI API Key
  if (openaiKey) {
    try {
      const fullResponse = await callOpenAIStreaming(openaiKey, model, systemPrompt, messages, temperature, onChunk);
      return fullResponse;
    } catch (err) {
      console.error("OpenAI API stream error, falling back to local engine:", err);
    }
  }

  // 3. Fallback Built-in Engine (Provides rich, contextual, simulated streaming response)
  return runFallbackEngine(messages, systemPrompt, onChunk);
}

async function callGeminiStreaming(
  apiKey: string,
  modelName: string,
  systemPrompt: string | undefined,
  messages: ChatHistoryItem[],
  temperature: number,
  onChunk: (chunk: string) => void
): Promise<string> {
  const targetModel = modelName.includes("gemini") ? modelName : "gemini-1.5-flash";
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${targetModel}:streamGenerateContent?alt=sse&key=${apiKey}`;

  const contents = messages
    .filter((m) => m.role !== "system")
    .map((m) => ({
      role: m.role === "assistant" ? "model" : "user",
      parts: [{ text: m.content }],
    }));

  const body: Record<string, unknown> = {
    contents,
    generationConfig: {
      temperature,
    },
  };

  if (systemPrompt) {
    body.systemInstruction = {
      parts: [{ text: systemPrompt }],
    };
  }

  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Gemini API returned ${response.status}: ${errorText}`);
  }

  const reader = response.body?.getReader();
  if (!reader) throw new Error("No response body from Gemini API");

  const decoder = new TextDecoder();
  let accumulatedText = "";
  let buffer = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() || "";

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith("data: ")) {
        const jsonStr = trimmed.substring(6);
        try {
          const parsed = JSON.parse(jsonStr);
          const candidate = parsed?.candidates?.[0];
          const textChunk = candidate?.content?.parts?.[0]?.text || "";
          if (textChunk) {
            accumulatedText += textChunk;
            onChunk(textChunk);
          }
        } catch {
          // Ignore partial or control json
        }
      }
    }
  }

  return accumulatedText;
}

async function callOpenAIStreaming(
  apiKey: string,
  modelName: string,
  systemPrompt: string | undefined,
  messages: ChatHistoryItem[],
  temperature: number,
  onChunk: (chunk: string) => void
): Promise<string> {
  const targetModel = modelName.includes("gpt") ? modelName : "gpt-4o-mini";
  const url = "https://api.openai.com/v1/chat/completions";

  const formattedMessages: { role: string; content: string }[] = [];
  if (systemPrompt) {
    formattedMessages.push({ role: "system", content: systemPrompt });
  }
  for (const m of messages) {
    formattedMessages.push({ role: m.role, content: m.content });
  }

  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: targetModel,
      messages: formattedMessages,
      temperature,
      stream: true,
    }),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`OpenAI API returned ${response.status}: ${errorText}`);
  }

  const reader = response.body?.getReader();
  if (!reader) throw new Error("No response body from OpenAI API");

  const decoder = new TextDecoder();
  let accumulatedText = "";
  let buffer = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() || "";

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed === "data: [DONE]") continue;
      if (trimmed.startsWith("data: ")) {
        try {
          const parsed = JSON.parse(trimmed.substring(6));
          const textChunk = parsed.choices?.[0]?.delta?.content || "";
          if (textChunk) {
            accumulatedText += textChunk;
            onChunk(textChunk);
          }
        } catch {
          // ignore parsing error
        }
      }
    }
  }

  return accumulatedText;
}

