import { NextRequest, NextResponse } from "next/server";
import { getAuthUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { streamLLMResponse, ChatHistoryItem } from "@/lib/llm";
import { rateLimit } from "@/lib/rate-limit";
import { sanitizeText } from "@/lib/security";

export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  try {
    const auth = await getAuthUser(req);
    if (!auth) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Rate limit prompt generation (e.g. 30 requests per minute)
    const rl = rateLimit(`chat:${auth.userId}`, { limit: 30, windowMs: 60 * 1000 });
    if (!rl.success) {
      return NextResponse.json(
        { error: "Too many requests. Please pause a moment." },
        { status: 429 }
      );
    }

    const body = await req.json();
    const { chatId, content } = body;

    if (!chatId || typeof chatId !== "string") {
      return NextResponse.json({ error: "Missing or invalid chatId" }, { status: 400 });
    }

    const cleanContent = sanitizeText(content || "").trim();
    if (!cleanContent) {
      return NextResponse.json({ error: "Message content cannot be empty" }, { status: 400 });
    }

    // Verify chat ownership
    const chat = await db.chat.findUnique({
      where: { id: chatId },
      include: {
        messages: {
          orderBy: { createdAt: "asc" },
          take: 20, // last 20 messages for context
        },
      },
    });

    if (!chat || chat.userId !== auth.userId) {
      return NextResponse.json({ error: "Chat not found" }, { status: 404 });
    }

    // Fetch user settings
    const settings = await db.userSettings.findUnique({
      where: { userId: auth.userId },
    });

    // Save user message to database
    await db.message.create({
      data: {
        chatId,
        role: "user",
        content: cleanContent,
      },
    });

    // Auto-generate title if it's the first message and title is "New Chat"
    if (chat.title === "New Chat" && chat.messages.length === 0) {
      const generatedTitle = cleanContent.slice(0, 36).replace(/\n/g, " ") + (cleanContent.length > 36 ? "..." : "");
      await db.chat.update({
        where: { id: chatId },
        data: { title: generatedTitle },
      });
    }

    // Prepare message history for context
    const history: ChatHistoryItem[] = chat.messages.map((m) => ({
      role: m.role as "user" | "assistant" | "system",
      content: m.content,
    }));
    history.push({ role: "user", content: cleanContent });

    // Setup streaming response
    const encoder = new TextEncoder();
    const customReadable = new ReadableStream({
      async start(controller) {
        let fullAssistantMessage = "";

        try {
          fullAssistantMessage = await streamLLMResponse({
            messages: history,
            systemPrompt: settings?.systemPrompt,
            model: settings?.model,
            temperature: settings?.temperature ?? 0.7,
            onChunk: (chunk: string) => {
              controller.enqueue(encoder.encode(chunk));
            },
          });

          // Save assistant message to database
          if (fullAssistantMessage) {
            await db.message.create({
              data: {
                chatId,
                role: "assistant",
                content: fullAssistantMessage,
              },
            });

            // Touch chat updatedAt
            await db.chat.update({
              where: { id: chatId },
              data: { updatedAt: new Date() },
            });
          }
        } catch (err) {
          console.error("Stream generation error:", err);
          controller.enqueue(encoder.encode("\n\n*[UMGN error: Failed to complete response]*"));
        } finally {
          controller.close();
        }
      },
    });

    return new Response(customReadable, {
      headers: {
        "Content-Type": "text/plain; charset=utf-8",
        "Cache-Control": "no-cache, no-transform",
        "Connection": "keep-alive",
      },
    });
  } catch (error) {
    console.error("Chat streaming route error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

